B.aIL=new A.ii("Son g\xfcncelleme: 18 Mart 2026",null)
B.aK0=new A.iG("Hizmet Tan\u0131m\u0131",null)
B.aIE=new A.ii("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aJX=new A.iG("Hesap ve Kay\u0131t",null)
B.aGs=new A.ep("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aGv=new A.ep("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aGe=new A.ep("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aK5=new A.iG("Kredi Sistemi",null)
